{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.budget import remaining"
  ],
  "tests": [
    {
      "name": "test_remaining_overspend_is_negative",
      "intent": "overspending returns a negative remaining amount",
      "code": "# intent: overspending returns a negative remaining amount\ndef test_remaining_overspend_is_negative():\n    assert remaining(Decimal(\"100.00\"), [Decimal(\"60.00\"), Decimal(\"55.00\")]) == Decimal(\"-15.00\")\n"
    },
    {
      "name": "test_remaining_exact_budget",
      "intent": "spending exactly the budget leaves zero",
      "code": "# intent: spending exactly the budget leaves zero\ndef test_remaining_exact_budget():\n    assert remaining(Decimal(\"100.00\"), [Decimal(\"100.00\")]) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_remaining_single_expense_capped_at_budget",
      "intent": "a single expense cannot exceed the budget, so it is capped",
      "code": "# intent: a single expense cannot exceed the budget, so it is capped\ndef test_remaining_single_expense_capped_at_budget():\n    assert remaining(Decimal(\"100.00\"), [Decimal(\"150.00\")]) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_remaining_multiple_expenses_each_capped",
      "intent": "each expense is capped at the budget before accumulating",
      "code": "# intent: each expense is capped at the budget before accumulating\ndef test_remaining_multiple_expenses_each_capped():\n    assert remaining(Decimal(\"100.00\"), [Decimal(\"150.00\"), Decimal(\"200.00\")]) == Decimal(\"-100.00\")\n"
    },
    {
      "name": "test_remaining_empty_spent_is_budget",
      "intent": "no spending returns the full budget",
      "code": "# intent: no spending returns the full budget\ndef test_remaining_empty_spent_is_budget():\n    assert remaining(Decimal(\"100.00\"), []) == Decimal(\"100.00\")\n"
    },
    {
      "name": "test_remaining_negative_spending_raises",
      "intent": "negative spending raises ValueError",
      "code": "# intent: negative spending raises ValueError\ndef test_remaining_negative_spending_raises():\n    with pytest.raises(ValueError):\n        remaining(Decimal(\"100.00\"), [Decimal(\"-5.00\")])\n"
    }
  ]
}
